package com.intellilib.server.web;
import com.intellilib.server.model.ApiModels.*; import com.intellilib.server.security.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService auth; public AuthController(AuthService a){auth=a;} @PostMapping("/card") public LoginResponse card(@RequestBody CardLoginRequest r){return auth.loginCard(r.cardToken(),r.workstationId());} @PostMapping("/admin") public LoginResponse admin(@RequestBody AdminLoginRequest r){return auth.loginAdmin(r.email(),r.password(),r.workstationId());} @PostMapping("/logout") public java.util.Map<String,Object> logout(HttpServletRequest r){auth.logout(AuthHeader.token(r));return java.util.Map.of("ok",true);} }
